/*
|--------------------------------------------------------------------------
| HELPERS
|--------------------------------------------------------------------------
*/

const getProductName = (
  product: Product,
) =>
  product.productName ||
  product.name ||
  product.title ||
  'Handcrafted Product';

const getProductDescription = (
  product: Product,
) =>
  product.shortDescription ||
  product.description ||
  product.fullDescription ||
  'Beautiful handmade craft created by a skilled artisan.';

const getProductPrice = (
  product: Product,
) => {
  const value =
    product.price ??
    product.amount ??
    product.recommendedPrice;

  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return 'Price on request';
  }

  const numeric = Number(value);

  if (Number.isNaN(numeric)) {
    return String(value);
  }

  return `₹${numeric.toLocaleString(
    'en-IN',
  )}`;
};

const getProductImage = (
  product: Product,
) =>
  product.enhancedImageUrl ||
  product.imageUrl ||
  product.image ||
  product.imageUri ||
  product.originalImageUrl;

const getProductAudio = (
  product: Product,
) =>
  product.audioUrl ||
  product.audioUri ||
  product.voiceUrl;

const getInitial = (
  name: string,
) =>
  name?.trim()?.charAt(0)?.toUpperCase() ||
  'A';

